#!/usr/bin/python3

def check_f(f, p, k):
    for i in range(p):
        if f[(k * i) % p] != (k * f[i]) % p:
            return False
    return True

def generate_f(f, p, k, index):
    if index == p:
        return check_f(f, p, k)
    total = 0
    for val in range(p):
        f.append(val)
        total += generate_f(f, p, k, index + 1)
        f.pop()
    return total

def process(p, k):
    total_count = 0
    visited_indices = set()
    for start_idx in range(p):
        if start_idx not in visited_indices:
            total_count += 1
        current_idx = start_idx
        while current_idx not in visited_indices:
            visited_indices.add(current_idx)
            current_idx = (current_idx * k) % p
    return pow(p, total_count - (k != 1), 10 ** 9 + 7)

p, k = map(int, input().split())
print(process(p, k))
